struct StaticRecipe {source:u32,far_view:bool,low_res_scale:f64,samplers:Vec<i32>,order:u32,slot:u32,object:u32}
mod static_world {
// Cold native static-world admission. CPU sources survive context loss; the
// journal records GPU recipes against their stable source ids.
use super::Bridge as BfeRenderer;
use bfe_render::static_world::{Geometry, Material, Record, Terrain};



impl BfeRenderer {
    pub fn static_terrain_layers(&self, source:u32, weights: &[u8]) -> u32 {
        self.static_sources.get(source as usize).map_or(0,|s|bfe_render::static_world::terrain_layer_mask(&s.record,weights))
    }
    // CPU source ownership survives a GPU context reset. Only this admission
    // copies authored arrays from the host; colour and depth share the result.
    pub fn static_source(&mut self, authored:&str, vertices:Vec<f32>, index:Vec<u32>)->Result<u32,String> {
        let record:Record=serde_json::from_str(authored).map_err(|e|String::from(&e.to_string()))?;
        let mut geometry=Geometry::new(&record,&vertices,&index).map_err(String::from)?;
        // TerrainPatches formerly retained a second full index array. Move it
        // into the shared source while keeping reduced indices and cell boxes.
        let mut terrain=record.terrain.then(||Terrain::new(&geometry));
        if let Some(t)=&mut terrain {geometry.index=std::mem::take(&mut t.full.index);}
        // CPU ids are append-only and outlive the replaceable GPU renderer.
        // Recovery recipes refer to these rows instead of journaling copies.
        let id=self.static_sources.len() as u32;
        self.static_sources.push(StaticSource {record,geometry,terrain,weights:vec![]});
        Ok(id)
    }
    pub fn static_source_weights(&mut self, id:u32, weights:&[u8])->Result<(),String> {
        // Optional weights can finish after the source is admitted. Updating
        // this cold payload does not mutate colour or depth geometry bytes.
        let source=self.static_sources.get_mut(id as usize).ok_or_else(||String::from("unknown static source"))?;
        source.weights.clear();
        if source.record.vertex_count.checked_mul(8)==Some(weights.len()) {source.weights.extend_from_slice(weights);}
        Ok(())
    }
    #[allow(clippy::too_many_arguments)]
    pub fn static_world(&mut self, source:u32, far_view:bool, low_res_scale:f64, samplers:&[i32], features:&[u32], order:u32, slot:u32, object:u32)->Result<u32,String> {
let resource=self.compile_static_world(source,far_view,low_res_scale,samplers,features,order,slot,object,None)?;
        self.static_recipes.push(super::StaticRecipe{source,far_view,low_res_scale,samplers:samplers.to_vec(),order,slot,object}); self.static_worlds.push(resource);
        Ok(resource.item)
    }
    // One typed settings command replaces every material version scan. Its
    // cold compiler shares the journal's retained authored streams and bytes.
    pub fn static_world_settings(&mut self, near: &[u32], far: &[u32]) -> Result<(),String> {
// Temporarily borrow the journal to apply typed settings in timeline
        // order; allocation commands retain stable ids during later recovery.
        let recipes=std::mem::take(&mut self.static_recipes);
        let result=(||{for (i,r) in recipes.iter().enumerate(){let old=self.static_worlds[i];self.compile_static_world(r.source,r.far_view,r.low_res_scale,&r.samplers,if old.far{far}else{near},r.order,r.slot,r.object,Some(old))?;}Ok(())})();
        self.static_recipes=recipes;
        result
    }
}

pub(super) struct StaticSource {pub record:Record,pub geometry:Geometry,pub terrain:Option<Terrain>,pub weights:Vec<u8>}
#[derive(Clone,Copy)]
pub(super) struct StaticSlot {pub far:bool,pub item:u32,pub geometry:u32}
impl BfeRenderer {
    #[allow(clippy::too_many_arguments)]
    pub(super) fn compile_static_world(&mut self, source:u32, far_view:bool, low_res_scale:f64, samplers:&[i32], features:&[u32], order:u32,slot:u32,object:u32,old:Option<StaticSlot>)->Result<StaticSlot,String> {
        let source=self.static_sources.get(source as usize).ok_or_else(||String::from("unknown static source"))?;
        // Near and low-resolution far terrain share immutable authored bytes.
        // Only their small material policy differs between the two views.
        let mut record=source.record.clone();record.far=far_view;record.low_res_scale=Some(low_res_scale);
        let geometry=&source.geometry;let weights=&source.weights;let terrain=&source.terrain;
        let material=Material::new(&record,geometry,weights,samplers,features).map_err(|e|String::from(&e))?;
        let mut bounds=geometry.bounds;
        if let Some(t)=terrain {bounds[..4].copy_from_slice(&t.sphere);}
        if samplers.iter().any(|id| *id>=0 && *id as usize >= self.r.core.native_texture_count()) { return Err(String::from("invalid world sampler")); }
        let spec = bfe_render::programs::spec(&material.key).map_err(|e|String::from(&e))?;
        let program=self.r.core.add_owned_program(&material.key).map_err(|e|String::from(&e))?;
        // Typed settings changes rebuild only a changed catalog variant.
        // Reusing geometry and item ids preserves visibility and draw order.
        if let Some(old)=old {
            let current=if old.far {self.r.far.program_id(old.item)} else {self.r.world.program_id(old.item)};
            if current==Some(program) {return Ok(old);}
        }
        let core = &mut self.r.core;
        let g=if let Some(old)=old {core.reset_geometry(old.geometry).map_err(|e|String::from(&e))?;old.geometry} else {core.add_geometry()};
        bfe_render::static_world::upload_geometry(core,g,geometry,spec.attributes).map_err(|e|String::from(&e))?;
        // Painted terrain weights are normalized bytes in a separate stream.
        // Missing or malformed optional files retain the two-layer variant.
        if bfe_render::static_world::terrain_layer_mask(&record, weights)!=0 && !record.far {
            let w = core.geometry_buffer(g, weights);
            for (name,location) in spec.attributes { if *name=="weights0" || *name=="weights1" {
                core.geometry_pointer(g,w,*location,4,glow::UNSIGNED_BYTE,true,8,if *name=="weights0" {0} else {4});
            }}
        }
        if !record.far {
            let world = &mut self.r.world;
            let id=if let Some(old)=old {world.reprogram(old.item,program);old.item} else {world.add_world(g, program, order, material.flags, &bounds)};
            // Material policy names only closed catalog uniforms and sampler
            // slots. The page never reflects or dispatches static uniforms.
            for (name,unit,texture) in &material.samplers { if spec.uniforms.iter().any(|(n,_)|n==name) { world.world_texture(core,id,*unit,*texture); } }
            for (name,value) in &material.values { world.world_uniform(core,id,name,value,false); }
            world.init_lamps(core,id);
            world.world_uniform(core,id,"receiveShadow",&[if material.receive_shadow { 1. } else { 0. }],true);
            // Culling cells are immutable resource state. A settings command
            // must not overwrite a frame's retained visibility/LOD state.
            if old.is_none() { if let Some(t) = &terrain {
                let ranges = t.full.cells.iter().flat_map(|c|[c[0] as u32,c[1] as u32]).collect::<Vec<_>>();
                let boxes = t.full.cells.iter().flat_map(|c|c[2..].iter().copied()).collect::<Vec<_>>();
                world.world_runs(id,&ranges,&boxes);
            } else if geometry.cells() { world.world_cells(id,&geometry.positions(),&geometry.index,48.); }}
            core.state.reset();
            Ok(StaticSlot {far:false,item:id,geometry:g})
        } else {
            // FarPass.registerItem's immutable table/sources/raster descriptor.
            // Only the numeric admission slot is written by the frame adapter.
            if slot as usize + usize::from(record.terrain) >= self.r.far.input.len() { return Err(String::from("far descriptor input capacity")); }
            let uniforms: Vec<_> = spec.uniforms.iter().filter(|(n,_)| !bfe_render::shader::FRAME_MEMBERS.iter().any(|(name,_)| n==name)).collect();
            let names = uniforms.iter().map(|(n,_)|*n).collect::<Vec<_>>().join(",");
            let types = uniforms.iter().map(|(_,ty)| match ty { 1=>glow::FLOAT,2=>glow::FLOAT_VEC2,3=>glow::FLOAT_VEC3,4=>glow::FLOAT_VEC4,5=>glow::INT,32=>glow::SAMPLER_2D,_=>0 }).collect::<Vec<_>>();
            let table = self.r.far.add_table(core,program,&names,&types,&vec![1;uniforms.len()]).ok_or_else(||String::from("invalid native far table"))?;
            let flags = (material.flags&3) | 4 | 8 | 16 | if material.flags&4!=0 { 32 } else { 0 } | if record.terrain { 0 } else { 256 };
            let id=if let Some(old)=old {self.r.far.reprogram(old.item,program,table);old.item} else {
                self.r.far.add_item(core,program,table,g,flags,glow::LEQUAL,&[0;6],&[0.,0.,order as f64,object as f64],&bounds[..4],slot)
            };
            for (u,(name,_)) in uniforms.iter().enumerate() {
                if let Some((_,_,texture)) = material.samplers.iter().find(|(n,_,_)|n==name) { self.r.far.source(id,u as u32,2,&[],*texture); }
                else if let Some(values) = material.values.get(name) { self.r.far.source(id,u as u32,0,values,0); }
                else { return Err(String::from(&format!("missing native far value {name}"))); }
            }
            // Culling cells are immutable resource state. A settings command
            // must not overwrite a frame's retained visibility/LOD state.
            if old.is_none() { if let Some(t) = &terrain {
                self.r.far.terrain(core,id,0,&geometry.index,&t.full.cells.iter().flatten().copied().collect::<Vec<_>>());
                self.r.far.terrain(core,id,1,&t.reduced.index,&t.reduced.cells.iter().flatten().copied().collect::<Vec<_>>());
            } else if geometry.cells() { self.r.far.cells(id,&geometry.positions(),&geometry.index,48.); }}
            core.state.reset();
            Ok(StaticSlot {far:true,item:id,geometry:g})
        }
    }
}

}
mod static_depth {
// Cold depth-resource admission from the same native source as world colour.
// The shadow adapter retains scene anchors and numeric ids, never CPU materials
// or attributes. GPU restoration repeats this recipe against the source bank.
use super::Bridge as BfeRenderer;
use bfe_render::static_depth::{DepthGeometry,Record};



impl BfeRenderer {
    pub fn static_depth_add(&mut self, source:u32, texture:i32)->Result<u32,String> {
if texture < -1 || texture>=0 && texture as usize>=self.r.core.native_texture_count() {return Err(String::from("unknown static depth sampler"));}
        if source as usize>=self.static_sources.len() {return Err(String::from("unknown static depth source"));}
        Ok(self.r.shadow.statics.admit(source,texture))
    }
    pub fn static_depth_replace(&mut self, id:u32, source:u32, texture:i32)->Result<u32,String> {
if texture < -1 || texture>=0 && texture as usize>=self.r.core.native_texture_count() {return Err(String::from("unknown static depth sampler"));}
        if source as usize>=self.static_sources.len() {return Err(String::from("unknown replacement depth source"));}
        if let Some(row)=self.r.shadow.statics.sources.get_mut(id as usize) {*row=bfe_render::static_depth::Source{source,texture};}
        Ok(id)
    }
    pub fn static_depth_finish(&mut self)->Result<String,String> {
// static_depth_finish replaces cold resource descriptions as a batch;
        // the live cascade boundary receives ids and one camera/time block.
        let refs=&self.r.shadow.statics.sources;
        let mut jobs=vec![];
        // mergeStaticShadows grouped opaque casters by shadowSide. The two
        // stable group ids retain their identity across material replacement.
        // worldMaterial sets shadowSide explicitly to its colour side,
        // overriding Three's usual front/back inversion for depth casters.
        for (id,side) in [(0,0),(1,2)] {
            let sources=refs.iter().filter_map(|r|self.static_sources.get(r.source as usize)).filter(|s|s.record.flags&2==0&&!s.geometry.fabric&&bfe_render::static_depth::shadow_side(&s.record)==side).map(|s|&s.geometry).collect::<Vec<_>>();
            if !sources.is_empty() {jobs.push((id,None,side,-1,"actors/depth-solid",DepthGeometry::merged(&sources)));}
        }
        // Cutouts retain each source's map and subdivision representation.
        // Native cells select the same Morton span as the old shadow proxies.
        for (i,row) in refs.iter().enumerate() {
            let source=&self.static_sources[row.source as usize];let cut=source.record.flags&2!=0;let fabric=source.geometry.fabric;
            if !cut&&!fabric {continue;}
            let key=match (fabric,cut) {(true,true)=>"actors/depth-fabric-cutout",(true,false)=>"actors/depth-fabric",(_,true)=>"actors/depth-cutout",_=>"actors/depth-solid"};
            jobs.push((i+2,Some(row.source),bfe_render::static_depth::shadow_side(&source.record),row.texture,key,DepthGeometry::cutout(&source.geometry)));
        }
        let n=refs.len()+2;
        self.r.shadow.statics.records.resize_with(n,||None);
        for record in self.r.shadow.statics.records.iter_mut().flatten() {record.active=false;}
        let mut nodes=vec![];
        for (id,source,side,texture,key,depth) in jobs {
            self.r.shadow.statics.clipped=self.r.shadow.statics.clipped.saturating_add(depth.clipped);
            let core=&mut self.r.core;
            let program=core.add_owned_program(key).map_err(|e|String::from(&e))?;
            let spec=bfe_render::programs::spec(key).map_err(|e|String::from(&e))?;
            // Reuse the logical geometry slot on replacement. Restoration can
            // replay the same allocation order without remapping scene anchors.
            let geometry=if let Some(old)=&self.r.shadow.statics.records[id] {core.reset_geometry(old.geometry).map_err(|e|String::from(&e))?;old.geometry} else {core.add_geometry()};
            bfe_render::static_world::upload_geometry(core,geometry,&depth.geometry,spec.attributes).map_err(|e|String::from(&e))?;
            // Resolve uniform names once at admission. Per-cascade writes use
            // numeric slots and fixed value kinds, matching the old depth pass.
            let mut uniforms=vec![];
            for (name,ty) in spec.uniforms {
                let kind=match *name {"modelViewMatrix"=>0,"viewMatrix"=>7,"projectionMatrix"=>1,"time"|"fabricTime"=>2,"map"=>3,"cut"|"alphaTest"=>4,"modelMatrix"=>5,"mapTransform"=>6,_=>return Err(String::from("unknown static depth uniform"))};
                if let Some(slot)=core.native_uniform_slot(program,name) {uniforms.push((slot,*ty,kind));}
            }
            let count=depth.geometry.index.len() as u32;let bounds=depth.geometry.bounds;
            self.r.shadow.statics.records[id]=Some(Record{geometry,program:program as usize,side,texture,bounds,cells:depth.cells,count,active:true,uniforms});
            nodes.push(serde_json::json!({"id":id,"source":source,"layer":depth.layer,"active":true}));
            core.state.reset();
        }
        // Hide an obsolete cutout anchor after an opaque replacement. Empty
        // side groups have no draw command but keep a stable scene identity.
        for id in 0..n {if self.r.shadow.statics.records[id].as_ref().is_none_or(|r|!r.active) {
            let source=if id<2 {None} else {Some(self.r.shadow.statics.sources[id-2].source)};
            nodes.push(serde_json::json!({"id":id,"source":source,"layer":2,"active":false}));
        }}
        self.r.shadow.reserve_static();
        serde_json::to_string(&serde_json::json!({"nodes":nodes,"capacity":(self.r.shadow.input.len()-bfe_render::shadow::S_FIRST)/bfe_render::shadow::DRAW})).map_err(|e|String::from(&e.to_string()))
    }
    pub fn static_depth_clipped(&self)->u32 {self.r.shadow.statics.clipped}
}

}
